[{"order":1,"type":"heading","text":"Parsing Request Bodies and Query Parameters in Express.js"},{"order":2,"type":"paragraph","text":"When building web applications and APIs with Express.js, handling incoming data is a fundamental task. This data typically arrives in two primary forms: query parameters (sent via the URL) and request bodies (sent via the payload of POST, PUT, or PATCH requests). Mastering how to parse both is essential for backend development."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before we begin parsing data, ensure you have Node.js and Express installed in your project. Older versions of Express required external packages like body-parser, but modern Express versions (4.16.0 and above) include built-in middleware for parsing JSON and URL-encoded data."},{"order":5,"type":"code","text":"const express = require('express');
const app = express();

// Built-in middleware to parse JSON bodies
app.use(express.json());

// Built-in middleware to parse URL-encoded bodies (HTML forms)
app.use(express.urlencoded({ extended: true }));

const PORT = process.0 || 3000;
app.listen(PORT, () => {
  console.log('Server is running on port ' + PORT);
});"},{"order":6,"type":"subheading","text":"Parsing Query Parameters"},{"order":7,"type":"paragraph","text":"Query parameters are appended to the URL after a question mark (?), separated by ampersands (&). Express automatically parses these parameters and populates them into the req.query object. They are typically used for filtering, sorting, or pagination."},{"order":8,"type":"code","text":"// Route: GET /search?term=javascript&page=2
app.get('/search', (req, res) => {
  const searchTerm = req.query.term;
  const pageNumber = req.query.page;

  res.json({
    message: 'Search results retrieved successfully',
    term: searchTerm,
    page: pageNumber
  });
});"},{"order":9,"type":"bullet_point","text":"req.query is a standard JavaScript object containing key-value pairs from the query string."},{"order":10,"type":"bullet_point","text":"If a query parameter is sent multiple times, Express parses it as an array (e.g., ?tag=node&tag=express becomes tags: ["node", "express"])."},{"order":11,"type":"subheading","text":"Parsing Request Bodies"},{"order":12,"type":"paragraph","text":"Request bodies contain data sent from clients, such as form submissions or JSON payloads from single-page applications. To access this data, you must use the appropriate middleware (express.json() or express.urlencoded()), which populates the req.body object."},{"order":13,"type":"code","text":"// Route: POST /users
app.post('/users', (req, res) => {
  const username = req.body.username;
  const email = req.body.email;

  if (!username || !email) {
    return res.status(400).json({ error: 'Username and email are required' });
  }

  // Simulate saving user to a database
  const newUser = {
    id: Date.now(),
    username,
    email
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});"},{"order":14,"type":"subheading","text":"Key Differences and Best Practices"},{"order":15,"type":"bullet_point","text":"Use req.query for optional parameters, pagination, searching, and filtering where the data is visible in the URL."},{"order":16,"type":"bullet_point","text":"Use req.body for sensitive data (like passwords), large payloads, and mutating operations (POST, PUT, PATCH)."},{"order":17,"type":"bullet_point","text":"Always validate and sanitize incoming data from both req.query and req.body using libraries like express-validator or Joi to prevent security vulnerabilities."}]
